WORD_RULES = [('Рыба и морепродукты', ['(^|[^а-я])сом([^а-я]|$)']), ('Зерновые и хлеб', ['(^|[^а-я])рис([^а-я]|$)'])]


def classify(name: str, fastdegree: str) -> str:
    if str(fastdegree or "").startswith("БАД"):
        return fastdegree
    n = name.lower().replace("ё", "е")
    for group, pats in WORD_RULES:
        for pat in pats:
            if re.search(pat, n):
                return group
    for group, keys in RULES:
        for k in keys:
            if k.replace("ё", "е") in n:
                return group
    return "Прочее"


def bracket_slice(text: str, start: int):
    depth = 0
    in_str = False
    esc = False
    for i, c in enumerate(text[start:], start):
        if in_str:
            if esc:
                esc = False
            elif c == "\\":
                esc = True
            elif c == '"':
                in_str = False
            continue
        if c == '"':
            in_str = True
            continue
        if c == "[":
            depth += 1
        elif c == "]":
            depth -= 1
            if depth == 0:
                return text[start : i + 1], i
    raise ValueError("unclosed")


def main() -> None:
    text = DS.read_text(encoding="utf-8")
    marker = "private products: any =\n"
    prod_arr = text.find(marker) + len(marker)
    prod_json, prod_end = bracket_slice(text, prod_arr)
    products = json.loads(prod_json)
    for p in products:
        p["group"] = classify(p["name"], p.get("fastdegree", ""))
    out = (
        "[\n"
        + ",\n".join(json.dumps(p, ensure_ascii=False, separators=(",", ":")) for p in products)
        + "]"
    )
    DS.write_text(text[:prod_arr] + out + text[prod_end + 1 :], encoding="utf-8")
    for g, n in Counter(p["group"] for p in products).most_common():
        print(f"{n:4} {g}")
    misc = [p["name"] for p in products if p["group"] == "Прочее"]
    if misc:
        print("Прочее:", len(misc), misc)


if __name__ == "__main__":
    main()
